// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;
import org.junit.jupiter.api.Test;

class LmdbNativeExactVariantForcingTest {

	@Test
	void aDecoratedKnownFamilyIsAForceableExactVariant() {
		assertThat(LmdbNativeForceableStrategies.isForceable("packedFtree(parallel)")).isTrue();
		assertThat(LmdbNativeForceableStrategies.isForceable("packedFtree(serial)")).isTrue();
		assertThat(LmdbNativeForceableStrategies.isForceable("unknown(parallel)")).isFalse();
		assertThat(LmdbNativeForceableStrategies.isForceable("packedFtree(parallel")).isFalse();
	}

	@Test
	void admissionRecognizesTheFamilyOfAnExactVariantRequest() {
		assertThat(LmdbNativeForceableStrategies.forces("packedFtree(parallel),nestedLoop", "packedFtree"))
				.isTrue();
	}

	@Test
	void anExactVariantWinsEvenWhenItsFamilyRivalIsCheaper() throws Exception {
		var serial = candidate("packedFtree(serial)", 1D, () -> "serial");
		var parallel = candidate("packedFtree(parallel)", 100D, () -> "parallel");
		assertThat(loop(serial, parallel).forcing("packedFtree(parallel)").dispatch(null).value())
				.isEqualTo("parallel");
	}

	@Test
	void aBareFamilyNameStillRanksAllOfItsVariants() throws Exception {
		var serial = candidate("packedFtree(serial)", 1D, () -> "serial");
		var parallel = candidate("packedFtree(parallel)", 100D, () -> "parallel");
		assertThat(loop(serial, parallel).forcing("packedFtree").dispatch(null).value()).isEqualTo("serial");
	}

	@Test
	void anUnavailableExactVariantNeverOpensTheFamilyRival() {
		AtomicInteger opened = new AtomicInteger();
		var serial = candidate("packedFtree(serial)", 1D, () -> {
			opened.incrementAndGet();
			return "serial";
		});
		assertThatThrownBy(() -> loop(serial).forcing("packedFtree(parallel)").dispatch(null))
				.isInstanceOf(QueryEvaluationException.class);
		assertThat(opened).hasValue(0);
	}

	@Test
	void anExactPreferenceDoesNotSilentlySkipToTheNextFamily() throws Exception {
		var parallel = candidate("packedFtree(parallel)", 100D, () -> "parallel");
		var fallback = candidate("nestedLoop", 1D, () -> "fallback");
		assertThat(loop(parallel, fallback).forcing("packedFtree(parallel),nestedLoop").dispatch(null).value())
				.isEqualTo("parallel");
	}

	@Test
	void aDecliningExactPreferenceRestoresTheNextFamily() throws Exception {
		var parallel = candidate("packedFtree(parallel)", 100D, () -> null);
		var fallback = candidate("nestedLoop", 1D, () -> "fallback");
		assertThat(loop(parallel, fallback).forcing("packedFtree(parallel),nestedLoop").dispatch(null).value())
				.isEqualTo("fallback");
	}

	@Test
	void commasInsideAVariantAreNotPreferenceSeparators() throws Exception {
		var serial = candidate("packedFtree(serial)", 1D, () -> "serial");
		var parallel = candidate("packedFtree(parallel,workers=4)", 100D, () -> "parallel");
		assertThat(loop(serial, parallel).forcing("packedFtree(parallel,workers=4)").dispatch(null).value())
				.isEqualTo("parallel");
	}

	@SafeVarargs
	private static LmdbNativeDispatchLoop<Void, String> loop(LmdbNativeCandidate<String>... candidates) {
		LmdbNativeStrategy<Void, String> family = LmdbNativeStrategy.of(LmdbNativeDecisionPoint.ROW,
				"variants", context -> LmdbNativeAdmission.of(List.of(candidates)));
		return new LmdbNativeDispatchLoop<>(LmdbNativeDecisionPoint.ROW, List.of(family), null);
	}

	private static LmdbNativeCandidate<String> candidate(String id, double count,
			LmdbNativeCandidate.Opener<String> opener) {
		return LmdbNativeCandidate.of(id, LmdbNativeCostQuote.streaming(
				LmdbNativeCostVector.point(Feature.SCANNED_ROW, count), 1D), opener);
	}
}
